  const t = token.toLowerCase();
  return pool.find(x => String(x.name || '').toLowerCase() === t)
    || pool.find(x => String(x.tab_id || '').toLowerCase() === t)
    || pool.find(x => String(x.name || '').toLowerCase().includes(t));
