      extra: { owned: 1, total: 1, detail_jump_url: '', duration: 5000, sort: 0, collection_completed: false,
        fetch_time: 0, benefit_jump_url: '', hidden: false, item_count: 1, click_guide: true },
      cover: sp.long || sp.def,
